@pytest.mark.pre_alloc_mutable
def test_create_large_result(
    state_test: StateTestFiller,
    pre: Alloc,
    tx_data_hex: str,
    expected_post: dict,
) -> None:
    """Ori Pomerantz   qbzzt1@gmail.com."""
    coinbase = Address("0x2adc25665018aa1fe0e6bc666dac8fc2697ff9ba")
    sender = Address("0xa94f5374fce5edbc8e2a8697c15331677e6ebf0b")
    contract = Address("0xcccccccccccccccccccccccccccccccccccccccc")
    callee = Address("0x000000000000000000000000000000000000c0de")

    env = Environment(
        fee_recipient=coinbase,
        number=1,
        timestamp=1000,
        prev_randao=0x20000,
        base_fee_per_gas=10,
        gas_limit=100000000,
    )

    pre[callee] = Account(
        balance=0,
        nonce=1,
        code=(
        Op.MSTORE(offset=0x0, value=Op.NOT(0x0))
        + Op.CODECOPY(dest_offset=Op.DUP1, offset=0x100, size=0x20)
        + Op.RETURN(offset=0x0, size=Op.MLOAD(offset=0x100))
    ),
    )
    pre[sender] = Account(balance=0xba1a9ce0ba1a9ce, nonce=1)
    pre[contract] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=1,
        code=(
        Op.SSTORE(key=0x1, value=Op.GAS) + Op.CALLDATALOAD(offset=0x4)
        + Op.CALLDATALOAD(offset=0x24) + Op.CALLDATALOAD(offset=0x44) + Op.SWAP1
        + Op.PUSH1[0x1] + Op.EXTCODESIZE(address=0xc0de)
        + Op.EXTCODECOPY(address=0xc0de, dest_offset=Op.DUP1, offset=0x0, size=Op.DUP1)
        + Op.SUB + Op.MSTORE8 + Op.PUSH2[0x100] + Op.MSTORE + Op.PUSH1[0x0] + Op.SWAP1
        + Op.JUMPI(pc=0x53, condition=Op.EQ(0xf0, Op.DUP1)) + Op.PUSH1[0xf5]
        + Op.JUMPI(pc=0x44, condition=Op.EQ) + Op.JUMPDEST
        + Op.SSTORE(key=0x0, value=Op.DUP1)
        + Op.SSTORE(key=0x1, value=Op.SUB(Op.SLOAD(key=0x1), Op.GAS))
        + Op.SSTORE(key=0x2, value=Op.EXTCODEHASH) + Op.STOP + Op.JUMPDEST + Op.POP
        + Op.CREATE2(value=Op.DUP1, offset=0x0, size=0x120, salt=0x5a17)
        + Op.JUMP(pc=0x32) + Op.JUMPDEST + Op.POP + Op.POP
        + Op.CREATE(value=Op.DUP1, offset=0x0, size=0x120) + Op.JUMP(pc=0x32)
    ),
        storage={0x0: 0x60a7, 0x1: 0x60a7, 0x2: 0x60a7},
    )

    tx_data = bytes.fromhex(tx_data_hex) if tx_data_hex else b""

    tx = Transaction(
        secret_key=Hash(
            "0x45a915e4d060149eb4365960e6a7a45f334393093061116b197e3240065ff2d8"
        ),
        to=contract,
        data=tx_data,
        gas_limit=80000000,
        gas_price=10,
        nonce=1,
        value=0,
    )

    post = expected_post

    state_test(env=env, pre=pre, post=post, tx=tx)
